/** Published evidence, never synthetic/live counters. Generated by publish-benchmarks.mjs. */
interface Evidence {
  schemaVersion: 1;
  status: "measured";
  measuredAt: string;
  core: {
    players: number;
    seconds: number;
    messagesPerSecond: number;
    ackP95Ms: number;
    tickP95Ms: number;
    soaked: boolean;
  };
  aoi: { players: number; reductionPercent: number } | null;
  environment: {
    cpu: string;
    logicalCores: number;
    ramMiB: number;
    os: string;
    node: string;
    commit: string;
    artifactSha256: string;
    tickRate: number;
    topology: string;
  };
  fullGame: { players: number; status: string } | null;
  reportUrl: string;
}
export async function installBenchmarkResults() {
  const section = document.querySelector<HTMLElement>(".tech-section");
  if (!section) return;
  try {
    const response = await fetch("/art/benchmark/latest.json", {
      cache: "no-cache",
    });
    if (!response.ok) return;
    const data = (await response.json()) as Evidence;
    if (
      data.schemaVersion !== 1 ||
      data.status !== "measured" ||
      !data.core.soaked ||
      !data.reportUrl.startsWith("/art/benchmark/")
    )
      return;
    const values = [
      data.core.players,
      data.core.messagesPerSecond,
      data.core.ackP95Ms,
      data.core.tickP95Ms,
      data.aoi?.reductionPercent ?? null,
    ];
    if (
      values
        .slice(0, 4)
        .some((v) => typeof v !== "number" || !Number.isFinite(v) || v < 0)
    )
      return;
    const cards = Array.from(
      section.querySelectorAll<HTMLElement>(".benchmarks article"),
    );
    const labels = [
      "ACTIVE PLAYERS TESTED",
      "PROTOCOL MESSAGES / SEC",
      "P95 APPLICATION LATENCY",
      "P95 WORLD UPDATE TIME",
      "AOI FAN-OUT REDUCTION",
    ];
    const notes = [
      `${Math.round(data.core.seconds / 60)}-minute distributed soak`,
      "Sustained inbound + outbound",
      "MOVE → authoritative ACK",
      `${data.environment.tickRate} Hz authoritative simulation`,
      data.aoi
        ? `${data.aoi.players}-player matched comparison`
        : "No passing paired run published",
    ];
    cards.forEach((card, i) => {
      card.querySelector("small")!.textContent = labels[i];
      const strong = card.querySelector("strong")!;
      strong.replaceChildren();
      const v = values[i];
      strong.append(
        document.createTextNode(
          v === null
            ? "—"
            : i < 2
              ? Math.round(v).toLocaleString("en-US")
              : v.toFixed(i === 3 ? 2 : 1),
        ),
      );
      if (i > 1) {
        const unit = document.createElement("i");
        unit.textContent = i === 4 ? " %" : " ms";
        strong.append(unit);
      }
      card.querySelector("span")!.textContent = notes[i];
    });
    const copy = section.querySelector<HTMLElement>(
      ".section-heading .section-copy",
    )!;
    copy.textContent = `Distributed, actively moving clients. An authoritative tick loop. Measured application latency. These results test the core engine independently of the event and contract workload.`;
    const note = section.querySelector<HTMLElement>(".benchmark-note")!;
    note.textContent = `Controlled loopback measurement · ${data.environment.node} · ${data.environment.tickRate} Hz · ${new Date(data.measuredAt).toLocaleDateString("en-GB")}.`;
    const details = document.createElement("details");
    details.className = "benchmark-methodology";
    const summary = document.createElement("summary");
    summary.textContent = "Test environment & methodology";
    const text = document.createElement("p");
    text.textContent = `${data.environment.cpu}, ${data.environment.logicalCores} logical cores, ${Math.round(data.environment.ramMiB / 1024)} GiB RAM, ${data.environment.os}. ${data.environment.topology} The figures describe this measured workload; they are not a hardware-independent maximum or a Render capacity claim.`;
    const full = document.createElement("p");
    full.textContent = data.fullGame
      ? `Full-game lobby/workbench load: ${data.fullGame.players} players, ${data.fullGame.status}. See the report for gates and limits.`
      : "The core result excludes the event/contract scheduler. Full-game correctness is reported separately.";
    const link = document.createElement("a");
    link.href = data.reportUrl;
    link.className = "text-link";
    link.textContent = "Read the full measured report ↗";
    details.append(summary, text, full, link);
    note.after(details);
  } catch {
    /* Offline or unpublished evidence keeps the honest placeholders. */
  }
}
